from scapy.all import *
import re
import urllib.parse
pcap = rdpcap('/home/ctfplayer/ctf_files/cap.pcap')

courses = []
for p in pcap:
    if p.haslayer('TCP') and p.haslayer('Raw'):
        payload = p['Raw'].load
        if b'POST' in payload and b'Content-Type: application/x-www-form-urlencoded' in payload:
            parts = payload.split(b'\\r\\n\\r\\n')
            if len(parts) > 1:
                form_data = parts[1].decode('utf-8', errors='ignore')
                # Extract course field
                course_match = re.search(r'c=([^&]+)', form_data)
                if course_match:
                    course = course_match.group(1)
                    course = urllib.parse.unquote_plus(course)
                    if course:
                        courses.append(course)

for i, course in enumerate(courses[:20]):
    print(f'{i+1}. {course}')
"

python3 -c "
from scapy.all import *
import re
pcap = rdpcap('/home/ctfplayer/ctf_files/cap.pcap')

grade_order = []
for p in pcap:
    if p.haslayer('TCP') and p.haslayer('Raw'):
        payload = p['Raw'].load
        if b'POST' in payload and b'Content-Type: application/x-www-form-urlencoded' in payload:
            parts = payload.split(b'\\r\\n\\r\\n')
            if len(parts) > 1:
                form_data = parts[1].decode('utf-8', errors='ignore')
                # Extract grade
                if 's=' in form_data:
                    match = re.search(r's=([^&]+)', form_data)
                    if match:
                        grade = match.group(1)
                        grade_order.append(grade)

# Converting to binary representations
binary_values = []
for grade in grade_order:
    if grade == 'A':
        binary_values.append('000')  # 0
    elif grade == 'B':
        binary_values.append('001')  # 1
    elif grade == 'C':
        binary_values.append('010')  # 2
    elif grade == 'D':
        binary_values.append('011')  # 3
    elif grade == 'E':
        binary_values.append('100')  # 4
    elif grade == 'F':
        binary_values.append('101')  # 5

binary_str = ''.join(binary_values)
print('Binary representation (3 bits per grade):')
print(binary_str)

# Convert binary to ASCII
for i in range(0, len(binary_str), 8):
    if i + 8 <= len(binary_str):
        byte = binary_str[i:i+8]
        try:
            ascii_val = int(byte, 2)
            ascii_char = chr(ascii_val)
            print(f'Binary {byte} = {ascii_val} = {ascii_char}')
        except:
            pass
"
